.sl-contact-image { background-color: var(--smartlearn-bg); color: var(--smartlearn-text); font-family: var(--smartlearn-body-font, system-ui, sans-serif); width: 100%; overflow-x: clip; }
.sl-contact-image .sl-split-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: stretch; }
.sl-contact-image .image-wrapper { min-height: 600px; position: relative; }
.sl-contact-image .sl-split-img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-contact-image .form-column { display: flex; align-items: center; justify-content: center; background-color: var(--smartlearn-bg); }
.sl-contact-image .form-wrapper { width: 100%; max-width: 640px; padding: clamp(2rem, 5vw, 4.5rem); }
.sl-contact-image .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-weight: 800; font-size: clamp(1.85rem, 3.5vw, 2.5rem); color: var(--smartlearn-text); margin: 0 0 0.75rem; }
.sl-contact-image .sl-subtitle { color: var(--smartlearn-text-muted); font-size: 1.075rem; line-height: 1.6; margin: 0 0 2rem; }
.sl-contact-image .sl-fields-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.25rem; }
.sl-contact-image .sl-field-full { grid-column: 1 / -1; }
.sl-contact-image .sl-label { display: block; font-weight: 600; font-size: 0.9rem; color: var(--smartlearn-text); margin-bottom: 0.4rem; }
.sl-contact-image .sl-input { width: 100%; min-height: 44px; padding: 0.625rem 0.875rem; border-radius: var(--smartlearn-radius, 0.5rem); background-color: var(--smartlearn-input-bg, var(--smartlearn-card-bg)); border: 1px solid var(--smartlearn-input-border, var(--smartlearn-card-border, rgba(148, 163, 184, 0.35))); color: var(--smartlearn-text); }
.sl-contact-image .sl-input:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 1px; border-color: var(--smartlearn-primary); }
.sl-contact-image .sl-submit-btn { min-height: 46px; padding: 0.75rem 2.5rem; border-radius: 999px; border: none; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-weight: 700; cursor: pointer; }
.sl-contact-image .sl-submit-btn:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); }
.sl-contact-image .sl-submit-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-contact-image .sl-form-status { margin-top: 1rem; font-size: 0.95rem; font-weight: 600; color: var(--smartlearn-primary); min-height: 1.25em; }
.sl-contact-image .sl-form-status.is-error { color: #dc2626; }
@media (max-width: 991px) { .sl-contact-image .sl-split-grid { grid-template-columns: 1fr; } .sl-contact-image .image-wrapper { min-height: 260px; max-height: 360px; } }
@media (max-width: 575px) { .sl-contact-image .sl-fields-grid { grid-template-columns: 1fr; } .sl-contact-image .sl-submit-btn { width: 100%; } }

